svg.script:
// Array configuration
const ARRAY_SIZE = 10;
const BAR_WIDTH = 60;
const BAR_GAP = 20;
const MAX_HEIGHT = 250;
const BASE_Y = 280;

// State
let array = [];
let isSorting = false;
let animationSpeed = 400;
let stepCount = 0;
let comparisonCount = 0;
let swapCount = 0;
let abortSort = false;

// Initialize array with random values
function initArray() {
  array = [];
  const values = [45, 80, 25, 60, 90, 35, 70, 15, 55, 40];
  for (let i = 0; i < ARRAY_SIZE; i++) {
    array.push({
      value: values[i],
      id: i,
      sorted: false
    });
  }
  stepCount = 0;
  comparisonCount = 0;
  swapCount = 0;
  abortSort = false;
  updateCounters();
  renderBars();
}

// Render bars
function renderBars() {
  const container = document.getElementById('bars-container');
  container.innerHTML = '';

  array.forEach((item, index) => {
    const barHeight = (item.value / 100) * MAX_HEIGHT;
    const x = index * (BAR_WIDTH + BAR_GAP);
    const y = BASE_Y - barHeight;

    // Create bar group
    const g = document.createElementNS('http://www.w3.org/2000/svg', 'g');
    g.setAttribute('id', `bar-${index}`);
    g.setAttribute('transform', `translate(${x}, 0)`);

    // Create rectangle
    const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
    rect.setAttribute('width', BAR_WIDTH);
    rect.setAttribute('height', barHeight);
    rect.setAttribute('y', y);
    rect.setAttribute('rx', 5);
    rect.setAttribute('fill', getBarFill(item));
    rect.setAttribute('stroke', '#2c3e50');
    rect.setAttribute('stroke-width', '1');
    rect.setAttribute('class', 'bar-rect');

    // Create value text
    const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
    text.setAttribute('x', BAR_WIDTH / 2);
    text.setAttribute('y', y + barHeight / 2 + 5);
    text.setAttribute('class', 'bar-value');
    text.textContent = item.value;

    // Create index label
    const indexLabel = document.createElementNS('http://www.w3.org/2000/svg', 'text');
    indexLabel.setAttribute('x', BAR_WIDTH / 2);
    indexLabel.setAttribute('y', BASE_Y + 20);
    indexLabel.setAttribute('class', 'legend-text');
    indexLabel.setAttribute('text-anchor', 'middle');
    indexLabel.textContent = index;

    g.appendChild(rect);
    g.appendChild(text);
    g.appendChild(indexLabel);
    container.appendChild(g);
  });
}

function getBarFill(item) {
  if (item.sorted) return 'url(#grad-sorted)';
  if (item.state === 'comparing') return 'url(#grad-compare)';
  if (item.state === 'swapping') return 'url(#grad-swap)';
  return 'url(#grad-default)';
}

function updateBar(index) {
  const barGroup = document.getElementById(`bar-${index}`);
  if (!barGroup) return;

  const item = array[index];
  const rect = barGroup.querySelector('.bar-rect');
  rect.setAttribute('fill', getBarFill(item));
}

function updateCounters() {
  document.getElementById('step-counter').textContent = stepCount;
  document.getElementById('comparison-counter').textContent = comparisonCount;
  document.getElementById('swap-counter').textContent = swapCount;
}

function setStatus(message) {
  document.getElementById('status-message').textContent = message;
}

function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

async function startSort() {
  if (isSorting) return;
  isSorting = true;
  abortSort = false;

  document.getElementById('btn-start').style.opacity = '0.5';
  document.getElementById('btn-start').style.pointerEvents = 'none';

  setStatus('Starting Bubble Sort...');
  await sleep(animationSpeed);

  const n = array.length;

  for (let i = 0; i < n - 1; i++) {
    if (abortSort) break;

    for (let j = 0; j < n - i - 1; j++) {
      if (abortSort) break;

      stepCount++;

      // Highlight elements being compared
      array[j].state = 'comparing';
      array[j + 1].state = 'comparing';
      updateBar(j);
      updateBar(j + 1);

      comparisonCount++;
      updateCounters();
      setStatus(`Comparing elements at positions ${j} and ${j + 1}: ${array[j].value} vs ${array[j + 1].value}`);
      await sleep(animationSpeed);

      if (array[j].value > array[j + 1].value) {
        // Swap needed
        setStatus(`${array[j].value} > ${array[j + 1].value}: Swapping elements`);
        array[j].state = 'swapping';
        array[j + 1].state = 'swapping';
        updateBar(j);
        updateBar(j + 1);
        await sleep(animationSpeed / 2);

        // Perform swap
        const temp = array[j];
        array[j] = array[j + 1];
        array[j + 1] = temp;
        swapCount++;
        updateCounters();

        // Re-render to show new positions
        renderBars();
        await sleep(animationSpeed / 2);
      } else {
        setStatus(`${array[j].value} ≤ ${array[j + 1].value}: No swap needed`);
        await sleep(animationSpeed / 2);
      }

      // Remove highlights
      array[j].state = null;
      array[j + 1].state = null;
      updateBar(j);
      updateBar(j + 1);
    }

    // Mark last element as sorted
    array[n - i - 1].sorted = true;
    updateBar(n - i - 1);
    setStatus(`Pass ${i + 1} complete. Element ${n - i - 1} is now in its final position.`);
    await sleep(animationSpeed);
  }

  // Mark first element as sorted too
  if (!abortSort && array.length > 0) {
    array[0].sorted = true;
    updateBar(0);
    setStatus('Sorting complete! Array is now sorted.');
  }

  isSorting = false;
  document.getElementById('btn-start').style.opacity = '1';
  document.getElementById('btn-start').style.pointerEvents = 'auto';
}

function resetSort() {
  abortSort = true;
  isSorting = false;
  document.getElementById('btn-start').style.opacity = '1';
  document.getElementById('btn-start').style.pointerEvents = 'auto';
  setTimeout(() => {
    initArray();
    setStatus('Click "Start Sort" to begin');
  }, 100);
}

function setSpeed(speed) {
  animationSpeed = speed;

  // Update button appearances
  document.getElementById('speed-slow').setAttribute('fill', speed === 800 ? '#3498db' : '#ecf0f1');
  document.getElementById('speed-slow').setAttribute('stroke', speed === 800 ? '#2980b9' : '#95a5a6');
  document.querySelector('#speed-slow + text').setAttribute('fill', speed === 800 ? 'white' : '#2c3e50');

  document.getElementById('speed-med').setAttribute('fill', speed === 400 ? '#3498db' : '#ecf0f1');
  document.getElementById('status-med').setAttribute('stroke', speed === 400 ? '#2980b9' : '#95a5a6');
  document.querySelector('#speed-med + text').setAttribute('fill', speed === 400 ? 'white' : '#2c3e50');

  document.getElementById('speed-fast').setAttribute('fill', speed === 150 ? '#3498db' : '#ecf0f1');
  document.getElementById('speed-fast').setAttribute('stroke', speed === 150 ? '#2980b9' : '#95a5a6');
  document.querySelector('#speed-fast + text').setAttribute('fill', speed === 150 ? 'white' : '#2c3e50');
}

// Initialize on load
initArray();
